'use strict';
// Сервер контроля доставки цветов. Без внешних зависимостей: нужен только Node.js 18+.
const http = require('http'), https = require('https'), fs = require('fs'), path = require('path'), crypto = require('crypto');

const PORT = +process.env.PORT || 3000;
const DATA_FILE = process.env.DATA_FILE || path.join(__dirname, 'data.json');
const PUB = path.join(__dirname, 'public');
const EMBED = {
  "manager.html": Buffer.from("", "base64"),
  "courier.html": Buffer.from("", "base64"),
  "order.html": Buffer.from("", "base64"),
  "common.js": Buffer.from("", "base64"),
  "i18n.js": Buffer.from("", "base64"),
  "i18n-m.js": Buffer.from("", "base64"),
  "manager.js": Buffer.from("", "base64"),
  "courier.js": Buffer.from("", "base64"),
  "style.css": Buffer.from("", "base64"),
  "pdf.js": Buffer.from("", "base64"),
  "manifest-m.json": Buffer.from("", "base64"),
  "manifest-c.json": Buffer.from("", "base64"),
  "sw.js": Buffer.from("", "base64"),
  "icon-192.png": Buffer.from("", "base64"),
  "icon-512.png": Buffer.from("", "base64"),
  "icon-180.png": Buffer.from("", "base64"),
};
const PHOTO_DIR = path.join(path.dirname(DATA_FILE), 'photos');
function rmPhoto(id) { try { fs.unlinkSync(path.join(PHOTO_DIR, id + '.jpg')); } catch (e) { /* файла нет */ } }
function rmAllPhotos() { try { fs.readdirSync(PHOTO_DIR).forEach(f => { try { fs.unlinkSync(path.join(PHOTO_DIR, f)); } catch (e) {} }); } catch (e) { /* папки нет */ } }
const CITY = process.env.GEO_CITY || 'Астана';
const COUNTRY = process.env.GEO_COUNTRY || 'kz';

const rnd = n => { let s = ''; while (s.length < n) s += crypto.randomInt(0, 10); return s; };
const tok = () => crypto.randomBytes(24).toString('hex');
const sha = s => crypto.createHash('sha256').update(String(s)).digest();
const str = (v, max) => typeof v === 'string' ? v.trim().slice(0, max) : '';
const num = (v, lo, hi) => { v = +v; return Number.isFinite(v) && v >= lo && v <= hi ? v : null; };
function bad(msg, status) { throw { status: status || 400, msg }; }
function hav(a, b) {
  const R = 6371, r = Math.PI / 180, dLat = (b.lat - a.lat) * r, dLng = (b.lng - a.lng) * r;
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

/* ---------- данные ---------- */
let db = { couriers: {}, orders: {}, nextOrderId: 1, settings: {} };
try { db = Object.assign(db, JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'))); } catch (e) { /* первый запуск */ }
const st = db.settings = db.settings || {};
if (!st.joinCode) st.joinCode = rnd(6);
if (typeof st.requirePhoto !== 'boolean') st.requirePhoto = true;
if (!st.depot) st.depot = { lat: 51.1694, lng: 71.4491 };
let pwdGenerated = false;
// MANAGER_PASSWORD может содержать несколько паролей через запятую. Пароль со звёздочкой в начале (например *7777) даёт роль главного менеджера,
// остальные пароли дают роль обычного менеджера. Звёздочка при входе не вводится. Пример: MANAGER_PASSWORD = 1234, *7777
// Если звёздочки нет ни у одного пароля, все входящие считаются главными (роли выключены).
const PW_LIST = String(process.env.MANAGER_PASSWORD || '').split(/[,;]/).map(x => x.trim()).filter(Boolean);
const PW_MAIN = PW_LIST.filter(x => x[0] === '*').map(x => x.slice(1)).filter(Boolean), PW_MGR = PW_LIST.filter(x => x[0] !== '*');
if (process.env.MAIN_PASSWORD) PW_MAIN.push(process.env.MAIN_PASSWORD);
if (PW_LIST.length) st.managerPassword = PW_MGR[0] || PW_MAIN[0] || '';
else if (!st.managerPassword) { st.managerPassword = rnd(8); pwdGenerated = true; }
if (!PW_LIST.length) PW_MGR.push(st.managerPassword);

let saveT = null;
function save() {
  clearTimeout(saveT);
  saveT = setTimeout(() => {
    try { const tmp = DATA_FILE + '.tmp'; fs.writeFileSync(tmp, JSON.stringify(db)); fs.renameSync(tmp, DATA_FILE); }
    catch (e) { console.error('Не удалось сохранить данные:', e.message); }
  }, 300);
}
save();

const managers = new Map(); // ключ входа -> { name, role }
// Роли включаются, если есть хотя бы один пароль главного менеджера (со звёздочкой в MANAGER_PASSWORD или MAIN_PASSWORD).
// Если MAIN_PASSWORD не задан, все вошедшие считаются главными (как раньше).
const ROLES_ON = PW_MAIN.length > 0;
// Номер заказа: 4-8 цифр, либо (для заказчиков из Instagram/Telegram) имя из 2-20 символов: буквы, цифры, @ . _ -
const normCode = x => { const t = String(x == null ? '' : x).trim().toLowerCase().replace(/\s+/g, ''); if (/^\d+$/.test(t)) return (t.length >= 4 && t.length <= 8) ? t : null; return /^[a-zа-яё0-9@._\-]{2,20}$/.test(t) ? t : null; };
const money = v => { if (v == null || v === '') return null; const n = Math.round(Number(String(v).replace(/[\s\u00a0]/g, '').replace(',', '.'))); if (!isFinite(n) || n < 0 || n > 1e9) bad('Сумма указана неверно (число от 0)'); return n; };

// Защита от подбора: считаем неудачные попытки за последние 10 минут.
const TRUST_PROXY = process.env.TRUST_PROXY === '1' || !!process.env.RENDER;
const hits = new Map();
function clientIp(req) {
  if (TRUST_PROXY) { const x = String(req.headers['x-forwarded-for'] || '').split(',').pop().trim(); if (x) return x; }
  return req.socket.remoteAddress || '?';
}
function blocked(key, max) { const a = (hits.get(key) || []).filter(t => Date.now() - t < 600000); hits.set(key, a); return a.length >= max; }
function fail(key) {
  const a = hits.get(key) || []; a.push(Date.now()); hits.set(key, a);
  if (hits.size > 5000) for (const [k, v] of hits) if (!v.length || Date.now() - v[v.length - 1] > 600000) hits.delete(k);
}

/* ---------- представления ---------- */
const pubCourier = c => ({ id: c.id, name: c.name, phone: c.phone, joinedAt: c.joinedAt, onShift: !!c.onShift, lat: c.lat == null ? null : c.lat, lng: c.lng == null ? null : c.lng, acc: c.acc || 0, ts: c.ts || 0 });
// Курьер получает заказ без телефона заказчика: только телефон получателя, чтобы позвонить.
const pubOrderC = o => { const x = pubOrder(o); x.hasCust = !!o.phone; if (!o.calledAt) delete x.phone; delete x.by; delete x.price; delete x.pay; delete x.returns; delete x.deliveredBy; delete x.note; delete x.ext; return x; };
const EXT = { yandex: 'Яндекс Go', indrive: 'inDrive' };
const pubOrder = o => ({ id: o.id, code: o.code, client: o.client, phone: o.phone || '', rphone: o.rphone || o.phone || '', addr: o.addr, entrance: o.entrance || '', apt: o.apt || '', note: o.note || '', by: o.by || '', deliveredBy: o.deliveredBy || '', returns: o.returns || [], price: o.price == null ? null : o.price, pay: o.pay == null ? null : o.pay, item: o.item, lat: o.lat, lng: o.lng, deadline: o.deadline, status: o.status, courierId: o.courierId || '', createdAt: o.createdAt, pickedAt: o.pickedAt || 0, deliveredAt: o.deliveredAt || 0, hasPhoto: !!o.hasPhoto, deliveredDistM: o.deliveredDistM == null ? null : o.deliveredDistM, calledAt: o.calledAt || 0, ext: o.ext || '' });

/* ---------- геокодер (OpenStreetMap Nominatim) ---------- */
let lastGeo = 0;
// Зона поиска: Астана и пригород в радиусе 40 км от центра (можно менять переменными GEO_LAT, GEO_LNG, GEO_RADIUS_KM).
const GEO_LAT = +process.env.GEO_LAT || 51.1694, GEO_LNG = +process.env.GEO_LNG || 71.4491, GEO_R = +process.env.GEO_RADIUS_KM || 40;
const dLat = GEO_R / 111, dLng = GEO_R / (111 * Math.cos(GEO_LAT * Math.PI / 180));
const VIEWBOX = [GEO_LNG - dLng, GEO_LAT + dLat, GEO_LNG + dLng, GEO_LAT - dLat].map(x => x.toFixed(5)).join(',');
function kmFromCenter(lat, lng) {
  const r = Math.PI / 180, a = Math.sin((lat - GEO_LAT) * r / 2) ** 2 + Math.cos(GEO_LAT * r) * Math.cos(lat * r) * Math.sin((lng - GEO_LNG) * r / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(a));
}
function geoOnce(q, cb) {
  const wait = Math.max(0, lastGeo + 1100 - Date.now());
  lastGeo = Date.now() + wait;
  setTimeout(() => {
    const p = '/search?format=json&limit=5&accept-language=ru&countrycodes=' + encodeURIComponent(COUNTRY) + '&viewbox=' + VIEWBOX + '&bounded=1&q=' + encodeURIComponent(q);
    const rq = https.get({ host: 'nominatim.openstreetmap.org', path: p, headers: { 'User-Agent': 'flower-dispatch/1.0' }, timeout: 8000 }, r => {
      let d = ''; r.on('data', x => { d += x; if (d.length > 200000) rq.destroy(); });
      r.on('end', () => { try { cb(null, JSON.parse(d).map(x => ({ lat: +x.lat, lng: +x.lon, name: String(x.display_name || '').slice(0, 140) })).filter(x => isFinite(x.lat) && isFinite(x.lng) && kmFromCenter(x.lat, x.lng) <= GEO_R).slice(0, 4)); } catch (e) { cb(e); } });
    });
    rq.on('error', cb); rq.on('timeout', () => rq.destroy(new Error('timeout')));
  }, wait);
}
// Попытки по очереди: как написано; с городом; только улица без номера дома.
function geocode(q, cb) {
  const clean = q.replace(/\s+/g, ' ').trim();
  const street = clean.replace(/[,\s]+(д\.?\s*)?\d+\s*([\/\-]\s*\d+)?\s*[а-яa-z]?(\s+(блок|корпус|корп\.?|стр\.?)\s*\S+)?\s*$/i, '').trim();
  const tries = [{ q: clean, approx: false }, { q: clean + ', ' + CITY, approx: false }];
  if (street && street.toLowerCase() !== clean.toLowerCase() && street.length >= 3) tries.push({ q: street, approx: true });
  let i = 0;
  const next = () => {
    if (i >= tries.length) return cb(null, []);
    const t = tries[i++];
    geoOnce(t.q, (err, r) => { if (err) return cb(err); if (r.length) return cb(null, r.map(x => Object.assign(x, { approx: t.approx }))); next(); });
  };
  next();
}

/* ---------- http ---------- */
const FILES = {
  '/m': ['manager.html', 'text/html; charset=utf-8'], '/c': ['courier.html', 'text/html; charset=utf-8'], '/z': ['order.html', 'text/html; charset=utf-8'],
  '/common.js': ['common.js', 'text/javascript; charset=utf-8'], '/i18n.js': ['i18n.js', 'text/javascript; charset=utf-8'], '/i18n-m.js': ['i18n-m.js', 'text/javascript; charset=utf-8'], '/manager.js': ['manager.js', 'text/javascript; charset=utf-8'],
  '/courier.js': ['courier.js', 'text/javascript; charset=utf-8'], '/style.css': ['style.css', 'text/css; charset=utf-8'], '/pdf.js': ['pdf.js', 'text/javascript; charset=utf-8'],
  '/manifest-m.json': ['manifest-m.json', 'application/manifest+json; charset=utf-8'], '/manifest-c.json': ['manifest-c.json', 'application/manifest+json; charset=utf-8'],
  '/sw.js': ['sw.js', 'text/javascript; charset=utf-8'], '/icon-192.png': ['icon-192.png', 'image/png'], '/icon-512.png': ['icon-512.png', 'image/png'], '/icon-180.png': ['icon-180.png', 'image/png']
};
function json(res, code, obj) {
  const b = JSON.stringify(obj);
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  res.end(b);
}
function readBody(req, max) {
  return new Promise((resolve, reject) => {
    let d = '';
    req.on('data', x => { d += x; if (d.length > max) { reject({ status: 413, msg: 'Слишком большой запрос' }); req.destroy(); } });
    req.on('end', () => { if (!d) return resolve({}); try { const j = JSON.parse(d); resolve(j && typeof j === 'object' ? j : {}); } catch (e) { reject({ status: 400, msg: 'Неверный формат' }); } });
    req.on('error', reject);
  });
}

const server = http.createServer(async (req, res) => {
  try {
    const u = new URL(req.url, 'http://x'), p = u.pathname;
    if (req.method === 'GET' && p === '/') { res.writeHead(302, { Location: '/m' }); return res.end(); }
    if (req.method === 'GET' && FILES[p]) {
      const f = FILES[p];
      res.writeHead(200, { 'Content-Type': f[1], 'Cache-Control': 'no-store, max-age=0', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer' });
      return res.end(f[0] === 'order.html' ? String(EMBED[f[0]]).replace('__WA__', String(process.env.WA_NUMBER || '77788785478').replace(/\D/g, '')) : EMBED[f[0]]);
    }
    if (p.startsWith('/api/')) return await api(req, res, u, p);
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end('Не найдено');
  } catch (e) {
    if (e && e.status) return json(res, e.status, { error: e.msg });
    console.error(e); json(res, 500, { error: 'Ошибка сервера' });
  }
});

async function api(req, res, u, p) {
  const m = req.method;
  const auth = (req.headers.authorization || '').replace(/^Bearer\s+/, '');
  const isM = !!auth && managers.has(auth);
  const cour = auth ? Object.values(db.couriers).find(c => c.token === auth) : null;
  // Большой запрос (фото) принимается только от зарегистрированного курьера и только на адрес доставки.
  const big = !!cour && /^\/api\/courier\/order\/\d+\/deliver$/.test(p);
  const b = m === 'POST' ? await readBody(req, big ? 1600000 : 50000) : {};
  const needM = () => { if (!isM) bad('Нужен вход менеджера', 401); };
  const needMain = () => { const x = managers.get(auth); if (!x || x.role !== 'main') bad('Это действие доступно только главному менеджеру', 403); };
  const needC = () => { if (!cour) bad('Нужна регистрация курьера', 401); };
  let mt;

  /* --- вход и регистрация --- */
  if (m === 'POST' && p === '/api/manager/login') {
    const ip = clientIp(req);
    if (blocked('L:' + ip, 8) || blocked('L:*', 60)) bad('Слишком много попыток. Подождите 10 минут.', 429);
    const given = sha(b.password || '');
    const isMain = PW_MAIN.map(x => crypto.timingSafeEqual(given, sha(x))).some(Boolean);
    const isMgr = PW_MGR.map(x => crypto.timingSafeEqual(given, sha(x))).some(Boolean);
    if (isMain || isMgr) {
      const mname = str(b.name, 30);
      if (mname.length < 2) bad('Введите своё имя (не короче 2 букв).', 400);
      hits.delete('L:' + ip);
      const role = (isMain || !ROLES_ON) ? 'main' : 'mgr';
      const t = tok(); managers.set(t, { name: mname, role }); return json(res, 200, { token: t, role });
    }
    fail('L:' + ip); fail('L:*');
    bad('Неверный пароль', 401);
  }
  if (m === 'POST' && p === '/api/courier/register') {
    const rip = 'R:' + clientIp(req);
    if (blocked(rip, 10)) bad('Слишком много попыток. Подождите 10 минут.', 429);
    const name = str(b.name, 30), phone = str(b.phone, 25);
    if (!name) bad('Введите имя');
    if (phone.replace(/\D/g, '').length < 7) bad('Введите телефон');
    if (str(b.joinCode, 10) !== st.joinCode) { fail(rip); bad('Неверный код смены. Уточните его у менеджера.', 403); }
    if (Object.keys(db.couriers).length >= 100) bad('Слишком много курьеров');
    const id = 'c' + crypto.randomBytes(4).toString('hex'), token = tok();
    db.couriers[id] = { id, name, phone, token, joinedAt: Date.now(), onShift: false, lat: null, lng: null, ts: 0 };
    save(); return json(res, 200, { id, token, name });
  }

  /* --- менеджер --- */
  if (p.startsWith('/api/manager/')) {
    needM();
    if (m === 'POST' && p === '/api/manager/logout') { managers.delete(auth); return json(res, 200, { ok: true }); }
    if (m === 'POST' && p === '/api/manager/settings') {
      needMain();
      if (typeof b.requirePhoto === 'boolean') st.requirePhoto = b.requirePhoto;
      save(); return json(res, 200, { requirePhoto: st.requirePhoto });
    }
    // Фото доставки видит только менеджер.
    if (m === 'GET' && (mt = p.match(/^\/api\/manager\/photo\/(\d+)$/))) {
      const o = db.orders[mt[1]]; if (!o || !o.hasPhoto) bad('Фото не найдено', 404);
      let buf; try { buf = fs.readFileSync(path.join(PHOTO_DIR, o.id + '.jpg')); } catch (e) { bad('Фото не найдено. Возможно, сервис перезапускался.', 404); }
      res.writeHead(200, { 'Content-Type': 'image/jpeg', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
      return res.end(buf);
    }
    if (m === 'GET' && p === '/api/manager/state') {
      const meM = managers.get(auth), isMainR = meM.role === 'main';
      return json(res, 200, {
        me: { name: meM.name, role: meM.role }, rolesOn: ROLES_ON,
        now: Date.now(), settings: { joinCode: st.joinCode, depot: st.depot, requirePhoto: st.requirePhoto },
        couriers: Object.values(db.couriers).sort((a, b) => a.joinedAt - b.joinedAt).map(pubCourier),
        orders: Object.values(db.orders).sort((a, b) => a.id - b.id).map(o => isMainR ? Object.assign(pubOrder(o), { log: o.log || [] }) : pubOrder(o))
      });
    }
    if (m === 'GET' && p === '/api/manager/geocode') {
      const q = str(u.searchParams.get('q'), 160); if (q.length < 3) bad('Введите адрес');
      return new Promise(resolve => geocode(q, (err, r) => { if (err) { json(res, 502, { error: 'Геокодер недоступен. Укажите точку кликом по карте.' }); } else json(res, 200, { results: r }); resolve(); }));
    }
    if (m === 'POST' && p === '/api/manager/order') {
      const phone = str(b.phone, 60), digits = phone.replace(/\D/g, '');
      const rphone = str(b.rphone, 25);
      if (rphone.replace(/\D/g, '').length < 7) bad('Введите телефон получателя, чтобы курьер мог позвонить');
      // Номер заказа: 4-8 цифр. Если не указан, берём последние 5 цифр телефона заказчика (если это телефон).
      let code = String(b.code == null ? '' : b.code).trim();
      if (!code) { const hm = phone.match(/@([a-zA-Z0-9._]{2,18})/); if (digits.length >= 9) code = digits.slice(-5); else if (hm) code = '@' + hm[1]; else bad('Укажите номер заказа (4-8 цифр или имя Instagram/Telegram) или телефон заказчика'); }
      code = normCode(code); if (!code) bad('Номер заказа: 4-8 цифр или имя до 20 символов (буквы, цифры, @ . _ -)');
      if (Object.values(db.orders).some(o => o.code === code && o.status !== 'delivered')) bad('Номер ' + code + ' уже занят незавершённым заказом. Укажите другой номер.');
      const lat = num(b.lat, -90, 90), lng = num(b.lng, -180, 180), deadline = num(b.deadline, 1e12, 9e15);
      if (lat == null || lng == null) bad('Не указана точка на карте');
      if (deadline == null) bad('Не указано время доставки');
      const addr = str(b.addr, 120); if (!addr) bad('Введите адрес');
      const id = db.nextOrderId++;
      db.orders[id] = { id, code, client: str(b.client, 40), phone, rphone, addr, entrance: str(b.entrance, 20), apt: str(b.apt, 20), note: str(b.note, 300), item: str(b.item, 60), lat, lng, deadline, status: 'new', courierId: '', by: (managers.get(auth) || {}).name || '', price: money(b.price), pay: money(b.pay), createdAt: Date.now() };
      save(); return json(res, 200, { order: pubOrder(db.orders[id]) });
    }
    if (m === 'POST' && (mt = p.match(/^\/api\/manager\/order\/(\d+)\/edit$/))) {
      const o = db.orders[mt[1]]; if (!o) bad('Заказ не найден', 404);
      const has = k => Object.prototype.hasOwnProperty.call(b, k), done = o.status === 'delivered', nw = {};
      if (has('price')) nw.price = money(b.price);
      if (has('pay')) nw.pay = money(b.pay);
      if (has('note')) nw.note = str(b.note, 300);
      if (!done) {
        if (has('client')) nw.client = str(b.client, 40);
        if (has('phone')) nw.phone = str(b.phone, 60);
        if (has('rphone')) { nw.rphone = str(b.rphone, 25); if (nw.rphone.replace(/\D/g, '').length < 7) bad('Введите телефон получателя, чтобы курьер мог позвонить'); }
        if (has('addr')) { nw.addr = str(b.addr, 120); if (!nw.addr) bad('Введите адрес'); }
        if (has('entrance')) nw.entrance = str(b.entrance, 20);
        if (has('apt')) nw.apt = str(b.apt, 20);
        if (has('item')) nw.item = str(b.item, 60);
        if (has('deadline')) { nw.deadline = num(b.deadline, 1e12, 9e15); if (nw.deadline == null) bad('Не указано время доставки'); }
        if (has('lat') || has('lng')) { nw.lat = num(b.lat, -90, 90); nw.lng = num(b.lng, -180, 180); if (nw.lat == null || nw.lng == null) bad('Точка указана неверно'); }
      }
      const NAMES = { price: 'стоимость', pay: 'выплата курьеру', note: 'пожелание', client: 'имя получателя', phone: 'тел. заказчика', rphone: 'тел. получателя', addr: 'адрес', entrance: 'подъезд', apt: 'кв.', item: 'состав', deadline: 'срок' };
      const ch = [];
      Object.keys(nw).forEach(k => {
        if (k === 'lat' || k === 'lng') return;
        const a = o[k] == null ? '' : o[k], z = nw[k] == null ? '' : nw[k];
        if (String(a) !== String(z)) { ch.push({ f: NAMES[k], from: String(a).slice(0, 60), to: String(z).slice(0, 60), k }); o[k] = nw[k]; }
      });
      if (nw.lat != null && (nw.lat !== o.lat || nw.lng !== o.lng)) { o.lat = nw.lat; o.lng = nw.lng; ch.push({ f: 'точка на карте', from: '', to: '', k: 'point' }); }
      if (ch.length) { o.log = (o.log || []).concat([{ t: Date.now(), by: (managers.get(auth) || {}).name || '', ch }]).slice(-40); save(); }
      return json(res, 200, { ok: true, changed: ch.length });
    }
    if (m === 'POST' && (mt = p.match(/^\/api\/manager\/order\/(\d+)\/(assign|unassign|delete)$/))) {
      const o = db.orders[mt[1]]; if (!o) bad('Заказ не найден', 404);
      if (mt[2] === 'delete') { needMain(); delete db.orders[o.id]; rmPhoto(o.id); }
      else if (mt[2] === 'unassign') { if (o.status === 'delivered') bad('Заказ уже доставлен'); if (o.courierId) o.returns = (o.returns || []).concat([{ n: (db.couriers[o.courierId] || {}).name || '?', t: Date.now(), how: 'снят менеджером ' + ((managers.get(auth) || {}).name || '') }]).slice(-10); o.courierId = ''; o.status = 'new'; o.pickedAt = 0; }
      else {
        if (o.status === 'delivered') bad('Заказ уже доставлен');
        if (o.ext) bad('Заказ передан в ' + EXT[o.ext] + '. Сначала снимите отметку.', 409);
        if (b.onlyNew && o.status !== 'new') bad('Заказ ' + o.code + ' уже назначен другому курьеру', 409);
        const c = db.couriers[b.courierId]; if (!c) bad('Курьер не найден', 404);
        o.courierId = c.id; o.status = 'picked'; o.pickedAt = Date.now();
      }
      save(); return json(res, 200, { ok: true });
    }
    if (m === 'POST' && (mt = p.match(/^\/api\/manager\/order\/(\d+)\/(ext|ext-done)$/))) {
      const o = db.orders[mt[1]]; if (!o) bad('Заказ не найден', 404);
      if (o.status === 'delivered') bad('Заказ уже доставлен');
      if (o.courierId) bad('Заказ уже у курьера. Сначала снимите его.', 409);
      if (mt[2] === 'ext') {
        const pr = String(b.provider || '');
        if (pr && !EXT[pr]) bad('Неизвестный сервис');
        if (pr) o.ext = pr; else delete o.ext;
      } else {
        if (!o.ext) bad('Сначала отметьте Яндекс Go или inDrive', 409);
        o.status = 'delivered'; o.deliveredAt = Date.now(); o.deliveredBy = EXT[o.ext];
      }
      save(); return json(res, 200, { ok: true });
    }
    if (m === 'POST' && (mt = p.match(/^\/api\/manager\/courier\/([\w]+)\/delete$/))) {
      needMain();
      const c = db.couriers[mt[1]]; if (!c) bad('Курьер не найден', 404);
      Object.values(db.orders).forEach(o => { if (o.courierId === c.id && o.status !== 'delivered') { o.returns = (o.returns || []).concat([{ n: c.name, t: Date.now(), how: 'курьер удалён менеджером' }]).slice(-10); o.courierId = ''; o.status = 'new'; } });
      delete db.couriers[c.id]; save(); return json(res, 200, { ok: true });
    }
    if (m === 'POST' && p === '/api/manager/joincode') { needMain(); st.joinCode = rnd(6); save(); return json(res, 200, { joinCode: st.joinCode }); }
    if (m === 'POST' && p === '/api/manager/depot') {
      needMain();
      const lat = num(b.lat, -90, 90), lng = num(b.lng, -180, 180); if (lat == null || lng == null) bad('Нет точки');
      st.depot = { lat, lng }; save(); return json(res, 200, { depot: st.depot });
    }
    // Новый день: удаляем заказы и всех курьеров (их доступ закрывается) и меняем код смены.
    if (m === 'POST' && p === '/api/manager/clear') { needMain(); db.orders = {}; db.couriers = {}; st.joinCode = rnd(6); rmAllPhotos(); save(); return json(res, 200, { ok: true }); }
    bad('Не найдено', 404);
  }

  /* --- курьер --- */
  if (p.startsWith('/api/courier/')) {
    needC();
    if (m === 'GET' && p === '/api/courier/state') {
      return json(res, 200, {
        now: Date.now(), depot: st.depot, requirePhoto: st.requirePhoto,
        me: { id: cour.id, name: cour.name, onShift: !!cour.onShift },
        orders: Object.values(db.orders).filter(o => o.courierId === cour.id).sort((a, b) => a.id - b.id).map(pubOrderC)
      });
    }
    if (m === 'POST' && p === '/api/courier/location') {
      const lat = num(b.lat, -90, 90), lng = num(b.lng, -180, 180); if (lat == null || lng == null) bad('Нет координат');
      cour.lat = lat; cour.lng = lng; cour.acc = Math.round(num(b.acc, 0, 100000) || 0); cour.ts = Date.now(); cour.onShift = true;
      save(); return json(res, 200, { ok: true });
    }
    if (m === 'POST' && p === '/api/courier/shift') {
      if (!b.on) {
        // Смену нельзя закончить, пока на курьере есть недоставленные заказы: их нужно доставить или вернуть менеджеру.
        const pend = Object.values(db.orders).filter(o => o.courierId === cour.id && o.status !== 'delivered');
        if (pend.length) bad('Нельзя закончить смену: у вас ' + pend.length + ' недоставленных заказов (' + pend.map(o => o.code).join(', ') + '). Доставьте их или верните менеджеру.');
      }
      cour.onShift = !!b.on; if (!cour.onShift) { cour.ts = 0; } save(); return json(res, 200, { ok: true });
    }
    if (m === 'POST' && p === '/api/courier/claim') {
      const ck = 'C:' + cour.id;
      if (blocked(ck, 15)) bad('Слишком много неверных кодов. Подождите 10 минут или спросите менеджера.', 429);
      const codes = Array.isArray(b.codes) ? b.codes.slice(0, 30).map(x => String(x).trim().toLowerCase().replace(/\s+/g, '')) : [];
      const results = codes.map(code => {
        if (!normCode(code)) { fail(ck); return { code, result: 'bad' }; }
        const o = Object.values(db.orders).find(x => x.code === code && x.status !== 'delivered');
        if (o && o.courierId === cour.id) return { code, result: 'yours' };
        // «нет такого заказа» и «заказ уже у другого курьера» выглядят одинаково: курьер не узнаёт о чужих заказах и курьерах
        if (!o || o.courierId || o.ext) { fail(ck); return { code, result: 'unavailable' }; }
        o.courierId = cour.id; o.status = 'picked'; o.pickedAt = Date.now();
        return { code, result: 'ok' };
      });
      save(); return json(res, 200, { results });
    }
    if (m === 'POST' && (mt = p.match(/^\/api\/courier\/order\/(\d+)\/(deliver|release|called)$/))) {
      const o = db.orders[mt[1]]; if (!o || o.courierId !== cour.id) bad('Заказ не найден', 404);
      if (mt[2] === 'called') { if (!o.calledAt) { o.calledAt = Date.now(); save(); } return json(res, 200, { ok: true }); }
      if (mt[2] === 'release') {
        if (o.status === 'delivered') bad('Заказ уже доставлен');
        o.returns = (o.returns || []).concat([{ n: cour.name, t: Date.now(), how: 'курьер вернул' }]).slice(-10);
        o.courierId = ''; o.status = 'new'; o.pickedAt = 0;
      } else {
        if (o.status === 'delivered') return json(res, 200, { ok: true });
        // Фото: JPEG до ~1,2 МБ. Если фото обязательно, без него доставка не отмечается.
        let photo = null;
        if (typeof b.photo === 'string' && b.photo) {
          const pm = b.photo.match(/^data:image\/jpeg;base64,([A-Za-z0-9+/=]+)$/);
          if (!pm) bad('Фото не подошло. Сделайте снимок ещё раз.');
          photo = Buffer.from(pm[1], 'base64');
          if (photo.length < 1000 || photo.length > 1200000 || photo[0] !== 0xFF || photo[1] !== 0xD8) bad('Фото не подошло. Сделайте снимок ещё раз.');
        }
        if (st.requirePhoto && !photo) bad('Сначала сделайте фото доставки');
        if (photo) {
          try { fs.mkdirSync(PHOTO_DIR, { recursive: true }); fs.writeFileSync(path.join(PHOTO_DIR, o.id + '.jpg'), photo); o.hasPhoto = true; }
          catch (e) { console.error('Не удалось сохранить фото:', e.message); if (st.requirePhoto) bad('Не удалось сохранить фото. Попробуйте ещё раз.', 500); }
        }
        o.status = 'delivered'; o.deliveredAt = Date.now(); o.deliveredBy = cour.name;
        const lat = num(b.lat, -90, 90), lng = num(b.lng, -180, 180);
        o.deliveredDistM = lat != null && lng != null ? Math.round(hav({ lat, lng }, o) * 1000) : null;
      }
      save(); return json(res, 200, { ok: true });
    }
    bad('Не найдено', 404);
  }
  bad('Не найдено', 404);
}

server.listen(PORT, () => {
  console.log('Сервер запущен: http://localhost:' + PORT);
  console.log('  Менеджер: /m    Курьеры: /c');
  console.log(pwdGenerated ? '  Пароль менеджера: ' + st.managerPassword + '  (создан автоматически; задать свой можно переменной MANAGER_PASSWORD)' : '  Пароли менеджеров заданы (' + (PW_MGR.length + PW_MAIN.length) + ' шт., главных: ' + PW_MAIN.length + ')');
  console.log('  Код смены для курьеров: ' + st.joinCode);
});
